-- 0019 part 2 of 4: High protein nutrition plans. Run the parts in order (part 1 adds the new foods).

-- High protein: 14 plans, 1,400 to 4,000 kcal.
delete from public.templates where kind = 'nutrition' and name like 'High protein, %kcal';
insert into public.templates (kind, name, summary, goal, level, audience, competitor, tags, body)
select 'nutrition', v.name, v.summary, v.goal, 'Beginner', 'any', 'any', v.tags::text[], v.body
from (values
('High protein, 1,400 kcal', '1,400 kcal (5,858 kJ). About 35% protein from lean meat, fish, eggs, dairy and a shake. Training and rest days, 3 meals and a snack.', 'Muscle gain', '{"high protein","trial","1400 kcal"}', $${"style":"plan","notes":"Eat roughly the same each day and don't stress about being exact. Hit your protein first. Training days swap the afternoon snack for a post-workout meal with more carbs. Weigh your food for the first week or two if you can, then hand portions are fine. Fill up on veg as much as you like.","day_types":[{"name":"Training day","weekdays":[1,2,4,5],"kcal":1400,"protein_g":139,"carbs_g":137,"fat_g":34,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":6,"fists":4,"cupped":5,"thumbs":3,"notes":"Post-workout meal within an hour or so of training.","meals":[{"name":"Breakfast","notes":"Swap: Greek yoghurt with a scoop of Per4m Isolate Zero and oats, or bacon medallions for the whole eggs.","items":[{"food":"Egg whites, liquid","grams":130},{"food":"Egg, whole","grams":100},{"food":"Wholemeal bread","grams":45},{"food":"Spinach","grams":45},{"food":"Avocado","grams":20}]},{"name":"Lunch","notes":"Swap: turkey mince, cod or tuna for the chicken; potatoes or a wrap for the rice.","items":[{"food":"Chicken breast, grilled","grams":120},{"food":"Basmati rice, cooked","grams":120},{"food":"Broccoli","grams":85},{"food":"Mixed salad leaves","grams":45},{"food":"Olive oil","grams":5}]},{"name":"Post-workout","notes":"Within an hour or so of training. Swap: Per4m Isolate Zero or Advanced Whey for the NiHPRO; rice cakes and honey for the cream of rice.","items":[{"food":"Strom NiHPRO Protein Isolate","grams":25},{"food":"Strom Cream of Rice","grams":30},{"food":"Banana","grams":60}]},{"name":"Dinner","notes":"Swap: turkey mince or chicken for the beef; rice or potatoes for the pasta.","items":[{"food":"Beef mince, 5% fat, raw","grams":130},{"food":"Pasta, dry","grams":45},{"food":"Tomato","grams":85},{"food":"Onion","grams":45},{"food":"Mushrooms","grams":45},{"food":"Mozzarella, light","grams":25}]}]},{"name":"Rest day","weekdays":[3,6,7],"kcal":1400,"protein_g":148,"carbs_g":118,"fat_g":38,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":6,"fists":4,"cupped":4,"thumbs":4,"notes":null,"meals":[{"name":"Breakfast","notes":"Swap: Greek yoghurt with a scoop of Per4m Isolate Zero and oats, or bacon medallions for the whole eggs.","items":[{"food":"Egg whites, liquid","grams":130},{"food":"Egg, whole","grams":100},{"food":"Wholemeal bread","grams":50},{"food":"Spinach","grams":45},{"food":"Avocado","grams":20}]},{"name":"Lunch","notes":"Swap: turkey mince, cod or tuna for the chicken; potatoes or a wrap for the rice.","items":[{"food":"Chicken breast, grilled","grams":120},{"food":"Basmati rice, cooked","grams":120},{"food":"Broccoli","grams":85},{"food":"Mixed salad leaves","grams":45},{"food":"Olive oil","grams":5}]},{"name":"Snack","notes":"Stir the protein into the yoghurt. Swap: skyr or cottage cheese for the yoghurt, or a Per4m Protein Bar.","items":[{"food":"Greek yoghurt, 0% fat","grams":130},{"food":"Per4m Isolate Zero","grams":15},{"food":"Frozen mixed berries","grams":60},{"food":"Almonds","grams":10}]},{"name":"Dinner","notes":"Swap: turkey mince or chicken for the beef; rice or potatoes for the pasta.","items":[{"food":"Beef mince, 5% fat, raw","grams":130},{"food":"Pasta, dry","grams":50},{"food":"Tomato","grams":85},{"food":"Onion","grams":45},{"food":"Mushrooms","grams":45},{"food":"Mozzarella, light","grams":25}]}]}]}$$::jsonb),
